//! Display names for the classifier's JSON IDs.
//!
//! The tables are generated by `build.rs` from `web/format.js`, the one
//! place IDs are mapped to names (AGENTS.md 4.1), so the desktop and the
//! browser always show the same text. The lookup functions mirror
//! `isaName`, `fmtFormatName` and `fmtCat` there, fallbacks included.

use serde::Serialize;
use zrax::types::{ExtensionCategory, FileFormat, Isa};

mod generated {
    include!(concat!(env!("OUT_DIR"), "/names.rs"));
}

fn lookup(table: &'static [(&'static str, &'static str)], id: &str) -> Option<&'static str> {
    table
        .binary_search_by(|(key, _)| (*key).cmp(id))
        .ok()
        .map(|index| table[index].1)
}

/// The ID a value has in payload JSON: the string of a plain enum variant,
/// or the JSON text of anything else (`{"unknown":3}`).
pub fn serde_id<T: Serialize>(value: &T) -> String {
    match serde_json::to_value(value) {
        Ok(serde_json::Value::String(id)) => id,
        Ok(other) => other.to_string(),
        Err(_) => String::new(),
    }
}

/// The JSON ID of an ISA (`arm`, `a_arch64`), shown where the browser shows
/// the raw tag.
pub fn isa_id(isa: Isa) -> String {
    serde_id(&isa)
}

/// The display name of an ISA: its table entry, or the ID with spaces for
/// underscores; `Unknown (0x…)` for a machine value zrax has no name for.
pub fn isa_name(isa: Isa) -> String {
    if let Isa::Unknown(machine) = isa {
        return format!("Unknown (0x{machine:X})");
    }
    let id = isa_id(isa);
    match lookup(generated::ISA_NAMES, &id) {
        Some(name) => name.to_string(),
        None => id.replace('_', " "),
    }
}

/// The display name of a file format: its table entry, or the uppercased
/// ID.
pub fn format_name(format: FileFormat) -> String {
    let id = serde_id(&format);
    match lookup(generated::FORMAT_NAMES, &id) {
        Some(name) => name.to_string(),
        None => id.to_uppercase(),
    }
}

/// The display name of an extension category: its table entry, or the ID.
pub fn category_name(category: ExtensionCategory) -> String {
    let id = serde_id(&category);
    match lookup(generated::CATEGORY_NAMES, &id) {
        Some(name) => name.to_string(),
        None => id,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_tables_are_sorted_for_binary_search() {
        for table in [
            generated::ISA_NAMES,
            generated::FORMAT_NAMES,
            generated::CATEGORY_NAMES,
        ] {
            assert_ne!(table.len(), 0);
            assert!(table.windows(2).all(|w| w[0].0 < w[1].0));
        }
    }

    #[test]
    fn names_come_from_the_browser_tables() {
        assert_eq!(isa_name(Isa::Arm), "ARM");
        assert_eq!(isa_id(Isa::AArch64), "a_arch64");
        assert_eq!(isa_name(Isa::AArch64), "AArch64");
        assert_eq!(format_name(FileFormat::Elf), "ELF");
        assert_eq!(category_name(ExtensionCategory::FloatingPoint), "FP");
        assert_eq!(category_name(ExtensionCategory::Other), "Other");
    }

    #[test]
    fn an_unnamed_machine_shows_its_value_in_hex() {
        assert_eq!(isa_name(Isa::Unknown(0x1F3)), "Unknown (0x1F3)");
    }

    #[test]
    fn an_id_without_a_table_entry_falls_back_as_in_the_browser() {
        assert_eq!(lookup(generated::ISA_NAMES, "no_such_isa"), None);
        assert_eq!(lookup(generated::FORMAT_NAMES, ""), None);
    }
}
